17	    private final Map<String, NivelClube> niveis;
18	    private final Map<String, Entrega> entregas;
19	    private final Map<String, Cupom> cupons;
20	    private final Map<String, FormaPagamento> pagamentos;
21	
22	    public ResumoService(List<NivelClube> niveis, List<Entrega> entregas, List<Cupom> cupons, List<FormaPagamento> pagamentos) {
23	        this.niveis = Identificavel.indexar(niveis);
24	        this.entregas = Identificavel.indexar(entregas);
25	        this.cupons = Identificavel.indexar(cupons);
26	        this.pagamentos = Identificavel.indexar(pagamentos);
27	    }
28	
29	    public ResumoResponse calcular(ResumoRequest req) {
30	        Pedido pedido = pedido(req);
31	        NivelClube nivel = obrigatorio(niveis, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
32	        Regiao regiao = regiao(req.regiao());
33	        Entrega entrega = obrigatorio(entregas, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
34	        exigir(entrega.atende(pedido), "MODALIDADE_INDISPONIVEL");
35	
36	        BigDecimal subtotal = pedido.subtotal();
37	        BigDecimal frete = nivel.frete(entrega.frete(pedido));
38	        BigDecimal desconto = descontoCupom(req.cupom(), pedido, frete);
39	        BigDecimal seguro = regiao.seguro(subtotal);
40	        BigDecimal total = subtotal.subtract(desconto).add(frete).add(seguro);
41	
42	        FormaPagamento pagamento = obrigatorio(pagamentos, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
43	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
44	        exigir(pagamento.aceitaParcelas(parcelas), "PARCELAMENTO_INVALIDO");
45	        exigir(pagamento.disponivel(total), "FORMA_PAGAMENTO_INDISPONIVEL");
46	        Cobranca cobranca = pagamento.cobrar(total, parcelas);
47	
48	        return new ResumoResponse(subtotal, desconto, frete, entrega.prazoDias(pedido), seguro,
49	                cobranca.totalFinal().subtract(total), cobranca.totalFinal(), parcelas, cobranca.valorParcela(),
50	                nivel.credito(subtotal), nivel.brinde(subtotal));
51	    }
52	
53	    private BigDecimal descontoCupom(String codigo, Pedido pedido, BigDecimal frete) {
54	        if (codigo == null) {
55	            return Dinheiro.valor("0");
56	        }
57	        Cupom cupom = obrigatorio(cupons, codigo, "CUPOM_INVALIDO");
58	        exigir(cupom.aplicavel(pedido, frete), "CUPOM_NAO_APLICAVEL");
59	        return cupom.desconto(pedido, frete);
60	    }
61	
62	    private Pedido pedido(ResumoRequest req) {
63	        List<ResumoRequest.Item> brutos = req.itens();
64	        exigir(brutos != null && !brutos.isEmpty() && brutos.stream().allMatch(ResumoService::itemValido), "PEDIDO_INVALIDO");
65	        return new Pedido(brutos.stream()
66	                .map(i -> new ItemCarrinho(i.nome(), i.precoUnitario(), i.quantidade(), i.pesoKg()))
67	                .toList());
68	    }
69	
70	    private static boolean itemValido(ResumoRequest.Item i) {
71	        return i != null
72	                && i.precoUnitario() != null && i.precoUnitario().signum() > 0
73	                && i.quantidade() != null && i.quantidade() > 0
74	                && i.pesoKg() != null && i.pesoKg().signum() > 0;
75	    }
76	
77	    private static Regiao regiao(String codigo) {
78	        try {
79	            return Regiao.valueOf(Objects.requireNonNull(codigo));
80	        } catch (IllegalArgumentException | NullPointerException e) {
81	            throw new PedidoRecusadoException("REGIAO_INVALIDA");
82	        }
83	    }
84	
85	    private static <T> T obrigatorio(Map<String, T> opcoes, String codigo, String erro) {
86	        T opcao = codigo == null ? null : opcoes.get(codigo);
87	        exigir(opcao != null, erro);
88	        return opcao;
89	    }
90	
91	    private static void exigir(boolean condicao, String erro) {
92	        if (!condicao) {
93	            throw new PedidoRecusadoException(erro);
94	        }
95	    }
96	}
