1	package br.loja.checkout.pagamento;
2	
3	import br.loja.checkout.Dinheiro;
4	import java.math.BigDecimal;
5	import java.math.MathContext;
6	import org.springframework.stereotype.Component;
7	
8	@Component
9	class Cartao implements FormaPagamento {
10	    private static final int MAX_PARCELAS = 12;
11	    private static final int MAX_PARCELAS_SEM_JUROS = 3;
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	
14	    @Override
15	    public String codigo() {
16	        return "CARTAO";
17	    }
18	
19	    @Override
20	    public boolean aceitaParcelas(int parcelas) {
21	        return parcelas >= 1 && parcelas <= MAX_PARCELAS;
22	    }
23	
24	    @Override
25	    public boolean disponivel(BigDecimal totalPedido) {
26	        return true;
27	    }
28	
29	    @Override
30	    public Cobranca cobrar(BigDecimal totalPedido, int parcelas) {
31	        if (parcelas <= MAX_PARCELAS_SEM_JUROS) {
32	            return new Cobranca(totalPedido, Dinheiro.arredondar(totalPedido.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)));
33	        }
34	        BigDecimal parcela = parcelaPrice(totalPedido, parcelas);
35	        return new Cobranca(Dinheiro.arredondar(parcela.multiply(BigDecimal.valueOf(parcelas))), parcela);
36	    }
37	
38	    /** Tabela Price: total × i ÷ (1 − (1 + i)^−n). */
39	    private BigDecimal parcelaPrice(BigDecimal total, int parcelas) {
40	        BigDecimal fator = BigDecimal.ONE.add(TAXA_MENSAL).pow(parcelas);
41	        BigDecimal denominador = BigDecimal.ONE.subtract(BigDecimal.ONE.divide(fator, MathContext.DECIMAL128));
42	        return Dinheiro.arredondar(total.multiply(TAXA_MENSAL).divide(denominador, MathContext.DECIMAL128));
43	    }
44	}
